message.content:
{
  "description": "The creature is shown in right-facing profile standing on a small patch of dirt with pebbles and sparse grass. It is a low, quadrupedal animal with a strongly arched back and a thick tapering tail extending off the left edge of the image. The dorsal surface, back, sides, outer surfaces of the limbs, top of the tail and top of the head are densely covered with overlapping, rounded, brown keratinous scales with darker centers and paler edges. The ventral surface, throat, underside of the tail, inner limbs, snout, and feet are pale pink, wrinkled, scaleless skin. The head is broad and blunt-snouted with large dark eyes ringed with pale blue and small nostrils. Seven pink, stalked, feathery external gills with fine branching filaments protrude from the neck just behind the head, four visible on the near side and three visible on the far side above the back. It has four short stout limbs ending in five-toed feet with small curved claws.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad, blunt and rounded, pale pink skin on the snout, throat and cheeks with small dark nostrils at the tip and large round dark eyes with a thin pale blue ring around the iris; the top of the head and crown are covered with small overlapping brown scales",
      "where": "at the front right end of the body, facing right"
    },
    {
      "part": "eyes",
      "looks_like": "large, round, dark brown/black with a light blue outer ring and a small highlight, with a slightly bulging appearance",
      "where": "on the sides of the head, one clearly visible on the near side and a second partially visible on the far side"
    },
    {
      "part": "gills",
      "looks_like": "seven pink fleshy stalks bearing dense, feathery, filamentous frills along their length, bright pink with darker pink filaments",
      "where": "clustered on the neck immediately behind the head, four stalks on the near (right) side of the neck and three stalks protruding above the back on the far (left) side"
    },
    {
      "part": "scales / plates",
      "looks_like": "overlapping, teardrop to rounded keratinous scales, brown with a darker brown center and a tan rim, arranged in regular diagonal rows like roof tiles, with fine striations visible on each scale",
      "where": "covering the entire dorsal surface from the top of the head down the back and sides, over the outer surfaces of all four limbs, and over the dorsal surface of the tail"
    },
    {
      "part": "skin / underparts / markings",
      "looks_like": "pale pink to off-white, soft, wrinkled skin with faint transverse folds on the belly and throat, no scales; the scales themselves have a two-tone brown marking with a darker center",
      "where": "on the ventral belly, throat, underside of the tail, inner limbs, snout, and feet; the brown marking is on each dorsal scale"
    },
    {
      "part": "legs",
      "looks_like": "short, stout and columnar, pale pink skin on the inner and lower portions and brown scales on the outer and upper portions, with wrinkled skin at the joints",
      "where": "four limbs positioned under the body, two forelimbs under the chest and two hindlimbs under the arched back"
    },
    {
      "part": "feet",
      "looks_like": "pale pink, five-toed, splayed, with short curved translucent claws at the tip of each toe and wrinkled skin over the toes and sole",
      "where": "at the distal end of each of the four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "thick at the base and tapering, pale pink wrinkled skin on the underside and brown overlapping scales on the dorsal side",
      "where": "extending from the rear left of the body, partially cropped by the left edge of the image"
    }
  ],
  "attached_objects": [],
  "animals": [
    "pangolin",
    "axolotl"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
